ok:['Словник щонайменше з 8 слів.','Переклад введеного слова через <code>get</code>.','Якщо слова немає — запропонуй додати переклад.','Виведи всі слова за алфавітом (<code>sorted</code>).','Міні-тест з 3 випадкових слів з підрахунком балів.'],
