 err:[`Звернення до напису до його створення — функція викликається раніше, ніж з'явилась змінна.`,`<code>label.text = "…"</code> не працює — використовуй <code>config(text=…)</code>.`,`Створення нового Label у кожному кліку замість зміни старого — написи накопичуються.`],
