 10:['Radiobutton(*6','Checkbutton(*2',['Перевірити',/\bif\b/],/config\w*\((?:[^()]|\([^()]*\))*\b(fg|bg|foreground|background)\s*=/,['Спочатку',/\.set\(/]],
